             record_id=record_id,
             run_id=run_id,
             timestamp=timestamp,
             entry_type=entry_type,
             payload=payload,
             rules_version=rules_version,
             supersedes=supersedes,
         )
         pref = payload_ref(payload)
         payload_text = canonical_json(payload).decode("utf-8")

