                     record_id, run_id, timestamp, entry_type, pref, rules_version,
                     prev_id, prev_hash, record_hash, supersedes, payload_text,
                 ),
             )
             sequence = int(cursor.lastrowid)
             self._conn.execute("COMMIT")
         except Exception:
             self._conn.execute("ROLLBACK")
