             record_id=record_id,
             run_id=run_id,
             timestamp=timestamp,
             entry_type=entry_type,
             payload=payload,
             rules_version=rules_version,
             previous_record_id=prev_id,
             previous_hash=prev_hash,
             record_hash=record_hash,
