         cannot make them inconsistent.
         """
         rows = self._snapshot()
         if not rows:
             return {"record_id": None, "record_hash": None, "count": 0}
         last = rows[-1]
         return {"record_id": last["record_id"], "record_hash": last["record_hash"], "count": len(rows)}


