     @staticmethod
     def _rows_to_records(rows: list[sqlite3.Row], run_id: str | None = None) -> list[AuditRecord]:
         records: list[AuditRecord] = []
         for row in rows:
             if run_id is not None and row["run_id"] != run_id:
